-- OFFLINE PG17 ONLY. Application create-only semantics, NOT native WORM.
-- Source-only lane. No processing/decoder/model eligibility or old receipt conversion.
DO $$BEGIN IF (current_database()<>'design_executor_synthetic' OR current_setting('design_executor.synthetic_fixture',true) IS DISTINCT FROM 'offline-stage6-only' OR current_setting('server_version_num')::int/10000<>17 OR to_regnamespace('design_identity') IS NULL OR to_regnamespace('design_content_manifest') IS NOT NULL) IS DISTINCT FROM false THEN RAISE EXCEPTION 'CONTENT_FIXTURE_REQUIRED';END IF;END$$;
CREATE ROLE design_content_storage_issuer LOGIN NOINHERIT NOSUPERUSER NOCREATEDB NOCREATEROLE NOREPLICATION NOBYPASSRLS;
CREATE ROLE design_content_capability NOLOGIN NOINHERIT NOSUPERUSER NOCREATEDB NOCREATEROLE NOREPLICATION NOBYPASSRLS;
GRANT CONNECT ON DATABASE design_executor_synthetic TO design_content_storage_issuer;
CREATE SCHEMA design_content_manifest AUTHORIZATION design_identity_owner;
REVOKE ALL ON SCHEMA design_content_manifest FROM PUBLIC,anon,authenticated;
GRANT USAGE ON SCHEMA design_content_manifest TO design_identity_runtime,design_content_storage_issuer,design_content_capability;
GRANT CREATE ON SCHEMA design_content_manifest TO design_content_capability;
GRANT USAGE ON SCHEMA design_identity TO design_content_capability;
GRANT EXECUTE ON FUNCTION design_identity.require_authority(),design_identity.resolve_hash(text,jsonb) TO design_content_capability;
CREATE TABLE design_content_manifest.config(singleton boolean PRIMARY KEY CHECK(singleton),project_origin text NOT NULL,bucket text NOT NULL);
CREATE TABLE design_content_manifest.permissions(id text PRIMARY KEY,write_id text NOT NULL UNIQUE,intent jsonb NOT NULL,expires_at timestamptz NOT NULL,active boolean NOT NULL DEFAULT true);
CREATE TABLE design_content_manifest.reservations(write_id text PRIMARY KEY,manifest_id text NOT NULL,expected_revision integer NOT NULL,intent jsonb NOT NULL,intent_digest text NOT NULL,permission_id text NOT NULL REFERENCES design_content_manifest.permissions);
CREATE TABLE design_content_manifest.claims(write_id text PRIMARY KEY REFERENCES design_content_manifest.reservations,claim_id text NOT NULL UNIQUE);
CREATE TABLE design_content_manifest.manifests(manifest_id text NOT NULL,revision integer NOT NULL,digest text NOT NULL,write_id text NOT NULL UNIQUE REFERENCES design_content_manifest.claims,record jsonb NOT NULL,PRIMARY KEY(manifest_id,revision));
CREATE TABLE design_content_manifest.read_grants(id text PRIMARY KEY,reference jsonb NOT NULL,authority jsonb NOT NULL,expires_at timestamptz NOT NULL,active boolean NOT NULL DEFAULT true);
CREATE TABLE design_content_manifest.terminations(write_id text PRIMARY KEY REFERENCES design_content_manifest.reservations,intent_digest text NOT NULL,claim_id text NOT NULL,reason text NOT NULL CHECK(reason='abandoned_no_retry'));
CREATE UNIQUE INDEX content_unique_target ON design_content_manifest.manifests((record->'target'));
CREATE FUNCTION design_content_manifest.immutable_row() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$BEGIN
 IF TG_OP='DELETE' OR TG_TABLE_NAME NOT IN ('permissions','read_grants') OR (to_jsonb(NEW)-'active') IS DISTINCT FROM (to_jsonb(OLD)-'active') OR to_jsonb(OLD)->'active' IS DISTINCT FROM 'true'::jsonb OR to_jsonb(NEW)->'active' IS DISTINCT FROM 'false'::jsonb THEN RAISE EXCEPTION 'CONTENT_IMMUTABLE' USING ERRCODE='42501';END IF;RETURN NEW;END$$;
DO $$DECLARE t text;BEGIN FOREACH t IN ARRAY ARRAY['config','permissions','reservations','claims','manifests','read_grants','terminations'] LOOP
 EXECUTE format('ALTER TABLE design_content_manifest.%I OWNER TO design_identity_owner',t);
 EXECUTE format('ALTER TABLE design_content_manifest.%I ENABLE ROW LEVEL SECURITY',t);EXECUTE format('ALTER TABLE design_content_manifest.%I FORCE ROW LEVEL SECURITY',t);
 EXECUTE format('CREATE POLICY capability_only ON design_content_manifest.%I TO design_content_capability USING(true) WITH CHECK(true)',t);
 EXECUTE format('GRANT SELECT ON design_content_manifest.%I TO design_content_capability',t);
 IF t<>'config' THEN EXECUTE format('GRANT INSERT ON design_content_manifest.%I TO design_content_capability',t);END IF;
 EXECUTE format('CREATE TRIGGER content_immutable BEFORE UPDATE OR DELETE ON design_content_manifest.%I FOR EACH ROW EXECUTE FUNCTION design_content_manifest.immutable_row()',t);
 END LOOP;END$$;
GRANT UPDATE(active) ON design_content_manifest.permissions,design_content_manifest.read_grants TO design_content_capability;
CREATE FUNCTION design_content_manifest.exact(v jsonb,k text[]) RETURNS boolean LANGUAGE sql IMMUTABLE SET search_path=pg_catalog AS $$SELECT coalesce(jsonb_typeof(v)='object' AND (SELECT array_agg(key ORDER BY key) FROM jsonb_object_keys(v) key)=(SELECT array_agg(x ORDER BY x) FROM unnest(k)x),false)$$;
CREATE FUNCTION design_content_manifest.canonical(v jsonb) RETURNS text LANGUAGE plpgsql IMMUTABLE SET search_path=pg_catalog AS $$DECLARE k text;x jsonb;r text;BEGIN CASE jsonb_typeof(v)
 WHEN 'object' THEN r:='';FOR k,x IN SELECT key,value FROM jsonb_each(v) ORDER BY key COLLATE "C" LOOP IF k!~'^[ -~]*$' THEN RAISE EXCEPTION 'CONTENT_INVALID';END IF;r:=r||CASE WHEN r='' THEN '' ELSE ',' END||to_jsonb(k)::text||':'||design_content_manifest.canonical(x);END LOOP;RETURN '{'||r||'}';
 WHEN 'array' THEN r:='';FOR x IN SELECT value FROM jsonb_array_elements(v) LOOP r:=r||CASE WHEN r='' THEN '' ELSE ',' END||design_content_manifest.canonical(x);END LOOP;RETURN '['||r||']';
 WHEN 'number' THEN IF v::text!~'^-?(0|[1-9][0-9]*)$' OR abs((v::text)::numeric)>9007199254740991 THEN RAISE EXCEPTION 'CONTENT_INVALID';END IF;RETURN v::text;
 WHEN 'string' THEN RETURN to_jsonb(v#>>'{}')::text;WHEN 'null' THEN RETURN 'null';WHEN 'boolean' THEN RETURN v::text;ELSE RAISE EXCEPTION 'CONTENT_INVALID';END CASE;END$$;
CREATE FUNCTION design_content_manifest.digest(v jsonb) RETURNS text LANGUAGE sql IMMUTABLE SET search_path=pg_catalog AS $$SELECT encode(sha256(convert_to(design_content_manifest.canonical(v),'UTF8')),'hex')$$;
CREATE FUNCTION design_content_manifest.owner_key(a jsonb) RETURNS text LANGUAGE sql IMMUTABLE SET search_path=pg_catalog AS $$SELECT design_content_manifest.digest(jsonb_build_array(a->'subjectId',a->'employmentId',a->'membershipId',a->'storeId'))$$;
CREATE FUNCTION design_content_manifest.write_id(a jsonb,rid text) RETURNS text LANGUAGE sql IMMUTABLE SET search_path=pg_catalog AS $$SELECT design_content_manifest.digest(jsonb_build_array(a->'subjectId',a->'employmentId',a->'membershipId',a->'storeId',rid))$$;
CREATE FUNCTION design_content_manifest.manifest_id(i jsonb) RETURNS text LANGUAGE sql IMMUTABLE SET search_path=pg_catalog AS $$SELECT 'content-manifest-'||design_content_manifest.digest(jsonb_build_object('schemaVersion','application-content-addressed-manifest-v1','ownerNamespaceDigest',design_content_manifest.owner_key(i->'authority'),'scopeDigest',design_content_manifest.digest(i->'authority'->'scope'),'assetId',i->'assetId'))$$;
CREATE FUNCTION design_content_manifest.auth() RETURNS jsonb LANGUAGE plpgsql SET search_path=pg_catalog AS $$BEGIN
 PERFORM pg_advisory_xact_lock(hashtextextended('design-prepared:transaction:v1',0));RETURN design_identity.require_authority();END$$;
CREATE FUNCTION design_content_manifest.resolve(token text,scope jsonb) RETURNS jsonb LANGUAGE plpgsql SET search_path=pg_catalog AS $$BEGIN
 IF token IS NULL OR length(token) NOT BETWEEN 32 AND 200 OR token~'[[:space:][:cntrl:]]' THEN RAISE EXCEPTION 'CONTENT_DENIED' USING ERRCODE='42501';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('design-prepared:transaction:v1',0));RETURN design_identity.resolve_hash(encode(sha256(convert_to(token,'UTF8')),'hex'),scope)->'authority';END$$;
CREATE FUNCTION design_content_manifest.check_intent(a jsonb,i jsonb) RETURNS text LANGUAGE plpgsql SET search_path=pg_catalog AS $$DECLARE cfg design_content_manifest.config;k text;BEGIN
 SELECT * INTO STRICT cfg FROM design_content_manifest.config WHERE singleton;
 IF (octet_length(i::text)>32768 OR NOT design_content_manifest.exact(i,ARRAY['schemaVersion','authority','requestId','assetId','role','expectedRevision','expectedManifestDigest','content','target','ancestry','processing','private','storageSemantics']) OR i->>'schemaVersion' IS DISTINCT FROM 'application-content-write-intent-v1' OR i->'authority' IS DISTINCT FROM a OR i->>'role' IS DISTINCT FROM 'source' OR i->'ancestry' IS DISTINCT FROM '{"source":null,"parent":null}'::jsonb OR i->'processing' IS DISTINCT FROM 'null'::jsonb OR i->'private' IS DISTINCT FROM 'true'::jsonb OR i->>'storageSemantics' IS DISTINCT FROM 'application_create_only_no_native_versions' OR jsonb_typeof(i->'requestId') IS DISTINCT FROM 'string' OR i->>'requestId'!~'^[A-Za-z0-9_-]{1,100}$' OR jsonb_typeof(i->'assetId') IS DISTINCT FROM 'string' OR i->>'assetId'!~'^[A-Za-z0-9_-]{1,100}$' OR jsonb_typeof(i->'expectedRevision') IS DISTINCT FROM 'number' OR i->>'expectedRevision'!~'^(0|[1-9][0-9]{0,2})$' OR NOT design_content_manifest.exact(i->'content',ARRAY['sha256','byteLength','mime']) OR jsonb_typeof(i->'content'->'sha256') IS DISTINCT FROM 'string' OR i->'content'->>'sha256'!~'^[a-f0-9]{64}$' OR jsonb_typeof(i->'content'->'byteLength') IS DISTINCT FROM 'number' OR i->'content'->>'byteLength'!~'^[1-9][0-9]{0,6}$' OR (i->'content'->>'byteLength')::bigint>8388608 OR jsonb_typeof(i->'content'->'mime') IS DISTINCT FROM 'string' OR i->'content'->>'mime' NOT IN ('image/jpeg','image/png','image/webp') OR NOT design_content_manifest.exact(i->'target',ARRAY['projectOrigin','bucket','key'])) IS DISTINCT FROM false THEN RAISE EXCEPTION 'CONTENT_INVALID' USING ERRCODE='42501';END IF;
 IF ((i->>'expectedRevision')::integer=0 AND i->'expectedManifestDigest' IS DISTINCT FROM 'null'::jsonb OR (i->>'expectedRevision')::integer>0 AND (jsonb_typeof(i->'expectedManifestDigest') IS DISTINCT FROM 'string' OR i->>'expectedManifestDigest'!~'^[a-f0-9]{64}$')) IS DISTINCT FROM false THEN RAISE EXCEPTION 'CONTENT_INVALID' USING ERRCODE='42501';END IF;
 k:='managed-content/v1/'||design_content_manifest.digest(a->'scope')||'/'||design_content_manifest.owner_key(a)||'/'||design_content_manifest.write_id(a,i->>'requestId')||'/'||(i->'content'->>'sha256');
 IF i->'target' IS DISTINCT FROM jsonb_build_object('projectOrigin',cfg.project_origin,'bucket',cfg.bucket,'key',k) THEN RAISE EXCEPTION 'CONTENT_TARGET_DENIED' USING ERRCODE='42501';END IF;
 RETURN design_content_manifest.digest(i);END$$;
CREATE FUNCTION design_content_manifest.permission(a jsonb,i jsonb) RETURNS design_content_manifest.permissions LANGUAGE plpgsql SET search_path=pg_catalog AS $$DECLARE p design_content_manifest.permissions;BEGIN
 PERFORM design_content_manifest.check_intent(a,i);SELECT * INTO STRICT p FROM design_content_manifest.permissions x WHERE x.write_id=design_content_manifest.write_id(a,i->>'requestId') FOR SHARE;
 IF (p.intent IS DISTINCT FROM i OR p.active IS DISTINCT FROM true OR p.expires_at<=clock_timestamp()) IS DISTINCT FROM false THEN RAISE EXCEPTION 'CONTENT_DENIED' USING ERRCODE='42501';END IF;RETURN p;END$$;
CREATE FUNCTION design_content_manifest.head_ok(i jsonb) RETURNS boolean LANGUAGE plpgsql SET search_path=pg_catalog AS $$DECLARE m design_content_manifest.manifests;BEGIN
 SELECT * INTO m FROM design_content_manifest.manifests x WHERE x.manifest_id=design_content_manifest.manifest_id(i) ORDER BY x.revision DESC LIMIT 1;
 IF NOT FOUND THEN IF i->'expectedRevision' IS DISTINCT FROM '0'::jsonb OR i->'expectedManifestDigest' IS DISTINCT FROM 'null'::jsonb THEN RAISE EXCEPTION 'CONTENT_HEAD_CHANGED' USING ERRCODE='42501';END IF;
 ELSIF m.revision IS DISTINCT FROM (i->>'expectedRevision')::int OR m.digest IS DISTINCT FROM i->>'expectedManifestDigest' OR m.record->'authority' IS DISTINCT FROM i->'authority' THEN RAISE EXCEPTION 'CONTENT_HEAD_CHANGED' USING ERRCODE='42501';END IF;RETURN true;END$$;
CREATE FUNCTION design_content_manifest.expected_manifest(i jsonb) RETURNS jsonb LANGUAGE sql IMMUTABLE SET search_path=pg_catalog AS $$SELECT jsonb_build_object('schemaVersion','application-content-addressed-manifest-v1','manifestId',design_content_manifest.manifest_id(i),'revision',(i->>'expectedRevision')::int+1,'previous',CASE WHEN (i->>'expectedRevision')::int=0 THEN 'null'::jsonb ELSE jsonb_build_object('revision',i->'expectedRevision','digest',i->'expectedManifestDigest') END,'intentDigest',design_content_manifest.digest(i),'authority',i->'authority','requestId',i->'requestId','assetId',i->'assetId','role',i->'role','content',i->'content','target',i->'target','ancestry',i->'ancestry','processing',i->'processing','private',true,'readbackAssertion','publisher_observed_matching_bytes','storageSemantics','application_create_only_no_native_versions')$$;
CREATE FUNCTION design_content_manifest.read_permission(a jsonb,m jsonb) RETURNS boolean LANGUAGE plpgsql SET search_path=pg_catalog AS $$DECLARE g design_content_manifest.read_grants;BEGIN
 SELECT * INTO STRICT g FROM design_content_manifest.read_grants x WHERE x.reference=jsonb_build_object('manifestId',m->'manifestId','revision',m->'revision','digest',design_content_manifest.digest(m)) AND x.authority=a AND x.active AND x.expires_at>clock_timestamp() ORDER BY x.expires_at DESC,x.id LIMIT 1 FOR SHARE;
 IF g.expires_at<=clock_timestamp() THEN RAISE EXCEPTION 'CONTENT_READ_DENIED' USING ERRCODE='42501';END IF;RETURN true;END$$;
CREATE FUNCTION design_content_manifest.context(a jsonb,rid text,access text DEFAULT 'write') RETURNS jsonb LANGUAGE plpgsql SET search_path=pg_catalog AS $$DECLARE r design_content_manifest.reservations;p design_content_manifest.permissions;c design_content_manifest.claims;m design_content_manifest.manifests;prior jsonb;st text;cid text;BEGIN
 IF rid IS NULL OR rid!~'^[A-Za-z0-9_-]{1,100}$' THEN RAISE EXCEPTION 'CONTENT_INVALID' USING ERRCODE='42501';END IF;
 SELECT * INTO STRICT r FROM design_content_manifest.reservations x WHERE x.write_id=design_content_manifest.write_id(a,rid);PERFORM design_content_manifest.check_intent(a,r.intent);SELECT * INTO STRICT p FROM design_content_manifest.permissions x WHERE x.id=r.permission_id;IF p.intent IS DISTINCT FROM r.intent THEN RAISE EXCEPTION 'CONTENT_DENIED' USING ERRCODE='42501';END IF;
 IF EXISTS(SELECT 1 FROM design_content_manifest.terminations x WHERE x.write_id=r.write_id) THEN RAISE EXCEPTION 'CONTENT_TERMINATED' USING ERRCODE='42501';END IF;
 IF r.permission_id IS DISTINCT FROM p.id OR r.intent_digest IS DISTINCT FROM design_content_manifest.digest(r.intent) OR r.manifest_id IS DISTINCT FROM design_content_manifest.manifest_id(r.intent) OR r.expected_revision IS DISTINCT FROM (r.intent->>'expectedRevision')::int THEN RAISE EXCEPTION 'CONTENT_DENIED' USING ERRCODE='42501';END IF;
 cid:='content-claim-'||design_content_manifest.digest(jsonb_build_object('writeId',r.write_id,'intentDigest',r.intent_digest));
 SELECT * INTO c FROM design_content_manifest.claims x WHERE x.write_id=r.write_id;st:=CASE WHEN FOUND THEN 'claimed' ELSE 'reserved' END;
 IF c.claim_id IS NOT NULL AND c.claim_id IS DISTINCT FROM cid THEN RAISE EXCEPTION 'CONTENT_DENIED' USING ERRCODE='42501';END IF;
 SELECT * INTO m FROM design_content_manifest.manifests x WHERE x.write_id=r.write_id;
 IF FOUND THEN IF c.claim_id IS NULL OR m.record IS DISTINCT FROM design_content_manifest.expected_manifest(r.intent) OR m.digest IS DISTINCT FROM design_content_manifest.digest(m.record) THEN RAISE EXCEPTION 'CONTENT_DENIED' USING ERRCODE='42501';END IF;st:='published';ELSE PERFORM design_content_manifest.head_ok(r.intent);END IF;
 IF access='write' THEN PERFORM design_content_manifest.permission(a,r.intent);ELSIF access='read' AND st='published' THEN PERFORM design_content_manifest.read_permission(a,m.record);ELSE RAISE EXCEPTION 'CONTENT_DENIED' USING ERRCODE='42501';END IF;
 prior:=NULL;IF r.expected_revision>0 THEN SELECT x.record INTO STRICT prior FROM design_content_manifest.manifests x WHERE x.manifest_id=r.manifest_id AND x.revision=r.expected_revision;IF design_content_manifest.digest(prior) IS DISTINCT FROM r.intent->>'expectedManifestDigest' OR prior->'authority' IS DISTINCT FROM a THEN RAISE EXCEPTION 'CONTENT_DENIED' USING ERRCODE='42501';END IF;END IF;
 RETURN jsonb_build_object('intent',r.intent,'previous',prior,'ancestors','[]'::jsonb,'claimId',cid,'state',st,'manifest',m.record);END$$;
CREATE FUNCTION design_content_manifest.reserve(i jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE a jsonb;p design_content_manifest.permissions;r design_content_manifest.reservations;wid text;BEGIN
 a:=design_content_manifest.auth();p:=design_content_manifest.permission(a,i);wid:=design_content_manifest.write_id(a,i->>'requestId');SELECT * INTO r FROM design_content_manifest.reservations x WHERE x.write_id=wid;
 IF FOUND THEN IF r.intent IS DISTINCT FROM i THEN RAISE EXCEPTION 'CONTENT_CONFLICT' USING ERRCODE='42501';END IF;ELSE PERFORM design_content_manifest.head_ok(i);IF EXISTS(SELECT 1 FROM design_content_manifest.reservations x WHERE x.manifest_id=design_content_manifest.manifest_id(i) AND x.expected_revision=(i->>'expectedRevision')::int AND NOT EXISTS(SELECT 1 FROM design_content_manifest.terminations t WHERE t.write_id=x.write_id)) THEN RAISE EXCEPTION 'CONTENT_HEAD_RESERVED' USING ERRCODE='42501';END IF;INSERT INTO design_content_manifest.reservations VALUES(wid,design_content_manifest.manifest_id(i),(i->>'expectedRevision')::int,i,design_content_manifest.digest(i),p.id);END IF;
 RETURN design_content_manifest.context(design_content_manifest.auth(),i->>'requestId');END$$;
CREATE FUNCTION design_content_manifest.checked(a jsonb,rid text,idigest text,cid text,access text DEFAULT 'write') RETURNS jsonb LANGUAGE plpgsql SET search_path=pg_catalog AS $$DECLARE ctx jsonb;BEGIN
 ctx:=design_content_manifest.context(a,rid,access);IF ctx->'intent'->>'requestId' IS DISTINCT FROM rid OR design_content_manifest.digest(ctx->'intent') IS DISTINCT FROM idigest OR ctx->>'claimId' IS DISTINCT FROM cid THEN RAISE EXCEPTION 'CONTENT_CONFLICT' USING ERRCODE='42501';END IF;RETURN ctx;END$$;
CREATE FUNCTION design_content_manifest.claim(rid text,idigest text,cid text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE ctx jsonb;n integer;BEGIN
 ctx:=design_content_manifest.checked(design_content_manifest.auth(),rid,idigest,cid);IF ctx->>'state'<>'reserved' THEN RETURN '{"created":false}'::jsonb;END IF;
 INSERT INTO design_content_manifest.claims VALUES(design_content_manifest.write_id(ctx->'intent'->'authority',rid),cid);PERFORM design_content_manifest.checked(design_content_manifest.auth(),rid,idigest,cid);RETURN '{"created":true}'::jsonb;END$$;
CREATE FUNCTION design_content_manifest.authorize(rid text,idigest text,cid text,phase text) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE ctx jsonb;BEGIN
 IF phase IS NULL OR phase NOT IN ('before_claim','before_put','before_read','before_publish','before_return','object_read_before','object_read_return') THEN RAISE EXCEPTION 'CONTENT_INVALID' USING ERRCODE='42501';END IF;
 ctx:=design_content_manifest.checked(design_content_manifest.auth(),rid,idigest,cid,CASE WHEN phase IN ('object_read_before','object_read_return') THEN 'read' ELSE 'write' END);
 IF phase='before_put' AND ctx->>'state'<>'claimed' OR phase='before_publish' AND ctx->>'state'='reserved' OR phase='before_read' AND ctx->>'state'<>'claimed' THEN RAISE EXCEPTION 'CONTENT_DENIED' USING ERRCODE='42501';END IF;
 PERFORM design_content_manifest.checked(design_content_manifest.auth(),rid,idigest,cid,CASE WHEN phase IN ('object_read_before','object_read_return') THEN 'read' ELSE 'write' END);RETURN true;END$$;
CREATE FUNCTION design_content_manifest.publish(rid text,idigest text,cid text,m jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE ctx jsonb;BEGIN
 ctx:=design_content_manifest.checked(design_content_manifest.auth(),rid,idigest,cid);
 IF ctx->>'state'='reserved' OR m IS DISTINCT FROM design_content_manifest.expected_manifest(ctx->'intent') THEN RAISE EXCEPTION 'CONTENT_DENIED' USING ERRCODE='42501';END IF;
 IF ctx->>'state'<>'published' THEN INSERT INTO design_content_manifest.manifests VALUES(m->>'manifestId',(m->>'revision')::int,design_content_manifest.digest(m),design_content_manifest.write_id(ctx->'intent'->'authority',rid),m);END IF;
 RETURN design_content_manifest.checked(design_content_manifest.auth(),rid,idigest,cid)->'manifest';END$$;
CREATE FUNCTION design_content_manifest.read_receipt(rid text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE ctx jsonb;BEGIN ctx:=design_content_manifest.context(design_content_manifest.auth(),rid);IF ctx IS DISTINCT FROM design_content_manifest.context(design_content_manifest.auth(),rid) THEN RAISE EXCEPTION 'CONTENT_CHANGED' USING ERRCODE='42501';END IF;RETURN ctx;END$$;
CREATE FUNCTION design_content_manifest.reconcile(rid text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE ctx jsonb;a jsonb;access text;BEGIN a:=design_content_manifest.auth();access:=CASE WHEN EXISTS(SELECT 1 FROM design_content_manifest.manifests x WHERE x.write_id=design_content_manifest.write_id(a,rid)) THEN 'read' ELSE 'write' END;ctx:=design_content_manifest.context(a,rid,access);IF ctx IS DISTINCT FROM design_content_manifest.context(design_content_manifest.auth(),rid,access) THEN RAISE EXCEPTION 'CONTENT_CHANGED' USING ERRCODE='42501';END IF;RETURN ctx;END$$;
CREATE FUNCTION design_content_manifest.read_manifest(ref jsonb,purpose text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE a jsonb;m design_content_manifest.manifests;ctx jsonb;BEGIN
 a:=design_content_manifest.auth();IF purpose IS NULL OR purpose NOT IN ('publication_receipt','object_read') THEN RAISE EXCEPTION 'CONTENT_INVALID' USING ERRCODE='42501';END IF;IF (NOT design_content_manifest.exact(ref,ARRAY['manifestId','revision','digest']) OR jsonb_typeof(ref->'revision') IS DISTINCT FROM 'number' OR ref->>'revision'!~'^[1-9][0-9]{0,3}$' OR (ref->>'revision')::int>1000 OR jsonb_typeof(ref->'manifestId') IS DISTINCT FROM 'string' OR jsonb_typeof(ref->'digest') IS DISTINCT FROM 'string' OR ref->>'manifestId'!~'^content-manifest-[a-f0-9]{64}$' OR ref->>'digest'!~'^[a-f0-9]{64}$') IS DISTINCT FROM false THEN RAISE EXCEPTION 'CONTENT_INVALID' USING ERRCODE='42501';END IF;
 SELECT * INTO STRICT m FROM design_content_manifest.manifests x WHERE x.manifest_id=ref->>'manifestId' AND x.revision=(ref->>'revision')::int;
 IF m.digest IS DISTINCT FROM ref->>'digest' OR m.record->'authority' IS DISTINCT FROM a THEN RAISE EXCEPTION 'CONTENT_DENIED' USING ERRCODE='42501';END IF;
 ctx:=design_content_manifest.context(a,m.record->>'requestId',CASE WHEN purpose='object_read' THEN 'read' ELSE 'write' END);IF ctx->'manifest' IS DISTINCT FROM m.record OR ctx IS DISTINCT FROM design_content_manifest.context(design_content_manifest.auth(),m.record->>'requestId',CASE WHEN purpose='object_read' THEN 'read' ELSE 'write' END) THEN RAISE EXCEPTION 'CONTENT_DENIED' USING ERRCODE='42501';END IF;RETURN ctx;END$$;
CREATE FUNCTION design_content_manifest.issue(token text,scope jsonb,pid text,i jsonb,ttl bigint) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE a jsonb;BEGIN
 IF session_user IS DISTINCT FROM 'design_content_storage_issuer' OR pid IS NULL OR pid!~'^[A-Za-z0-9_-]{1,100}$' OR ttl IS NULL OR ttl NOT BETWEEN 1 AND 900000 THEN RAISE EXCEPTION 'CONTENT_DENIED' USING ERRCODE='42501';END IF;
 a:=design_content_manifest.resolve(token,scope);PERFORM design_content_manifest.check_intent(a,i);PERFORM design_content_manifest.head_ok(i);
 INSERT INTO design_content_manifest.permissions VALUES(pid,design_content_manifest.write_id(a,i->>'requestId'),i,clock_timestamp()+ttl*interval '1 millisecond',true);
 PERFORM design_content_manifest.permission(design_content_manifest.resolve(token,scope),i);RETURN true;END$$;
CREATE FUNCTION design_content_manifest.revoke(pid text) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE n integer;BEGIN
 IF session_user IS DISTINCT FROM 'design_content_storage_issuer' OR pid IS NULL OR pid!~'^[A-Za-z0-9_-]{1,100}$' THEN RAISE EXCEPTION 'CONTENT_DENIED' USING ERRCODE='42501';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('design-prepared:transaction:v1',0));UPDATE design_content_manifest.permissions x SET active=false WHERE x.id=pid AND x.active;GET DIAGNOSTICS n=ROW_COUNT;RETURN n=1;END$$;
-- Read grants are independent of the original write TTL and cannot create claims.
CREATE FUNCTION design_content_manifest.issue_read(token text,scope jsonb,pid text,ref jsonb,ttl bigint) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE a jsonb;m design_content_manifest.manifests;BEGIN
 IF session_user IS DISTINCT FROM 'design_content_storage_issuer' OR pid IS NULL OR pid!~'^[A-Za-z0-9_-]{1,100}$' OR ttl IS NULL OR ttl NOT BETWEEN 1 AND 900000 THEN RAISE EXCEPTION 'CONTENT_DENIED' USING ERRCODE='42501';END IF;
 a:=design_content_manifest.resolve(token,scope);SELECT * INTO STRICT m FROM design_content_manifest.manifests x WHERE jsonb_build_object('manifestId',x.manifest_id,'revision',x.revision,'digest',x.digest)=ref;
 IF m.record->'authority' IS DISTINCT FROM a OR m.digest IS DISTINCT FROM design_content_manifest.digest(m.record) THEN RAISE EXCEPTION 'CONTENT_DENIED' USING ERRCODE='42501';END IF;
 INSERT INTO design_content_manifest.read_grants VALUES(pid,ref,a,clock_timestamp()+ttl*interval '1 millisecond',true);PERFORM design_content_manifest.read_permission(design_content_manifest.resolve(token,scope),m.record);RETURN true;END$$;
CREATE FUNCTION design_content_manifest.revoke_read(pid text) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE n integer;BEGIN
 IF session_user IS DISTINCT FROM 'design_content_storage_issuer' OR pid IS NULL OR pid!~'^[A-Za-z0-9_-]{1,100}$' THEN RAISE EXCEPTION 'CONTENT_DENIED' USING ERRCODE='42501';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('design-prepared:transaction:v1',0));UPDATE design_content_manifest.read_grants x SET active=false WHERE x.id=pid AND x.active;GET DIAGNOSTICS n=ROW_COUNT;RETURN n=1;END$$;
-- Termination frees only an unpublished head. Old request/claim is never reused;
-- a late external PUT may be an orphan, and this command makes no deletion claim.
CREATE FUNCTION design_content_manifest.terminate(token text,scope jsonb,rid text,idigest text,cid text) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE a jsonb;r design_content_manifest.reservations;BEGIN
 IF session_user IS DISTINCT FROM 'design_content_storage_issuer' THEN RAISE EXCEPTION 'CONTENT_DENIED' USING ERRCODE='42501';END IF;a:=design_content_manifest.resolve(token,scope);
 SELECT * INTO STRICT r FROM design_content_manifest.reservations x WHERE x.write_id=design_content_manifest.write_id(a,rid);
 IF r.intent->'authority' IS DISTINCT FROM a OR r.intent_digest IS DISTINCT FROM idigest OR cid IS DISTINCT FROM 'content-claim-'||design_content_manifest.digest(jsonb_build_object('writeId',r.write_id,'intentDigest',r.intent_digest)) OR EXISTS(SELECT 1 FROM design_content_manifest.manifests x WHERE x.write_id=r.write_id) THEN RAISE EXCEPTION 'CONTENT_DENIED' USING ERRCODE='42501';END IF;
 INSERT INTO design_content_manifest.terminations VALUES(r.write_id,idigest,cid,'abandoned_no_retry') ON CONFLICT(write_id) DO NOTHING;
 IF design_content_manifest.resolve(token,scope) IS DISTINCT FROM a THEN RAISE EXCEPTION 'CONTENT_DENIED' USING ERRCODE='42501';END IF;RETURN true;END$$;
DO $$DECLARE f record;BEGIN FOR f IN SELECT p.oid::regprocedure sig FROM pg_proc p WHERE p.pronamespace='design_content_manifest'::regnamespace LOOP EXECUTE format('ALTER FUNCTION %s OWNER TO design_content_capability',f.sig);EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC,anon,authenticated,design_identity_runtime,design_content_storage_issuer',f.sig);END LOOP;END$$;
GRANT EXECUTE ON FUNCTION design_content_manifest.reserve(jsonb),design_content_manifest.claim(text,text,text),design_content_manifest.authorize(text,text,text,text),design_content_manifest.publish(text,text,text,jsonb),design_content_manifest.reconcile(text),design_content_manifest.read_manifest(jsonb,text),design_content_manifest.read_receipt(text) TO design_identity_runtime;
GRANT EXECUTE ON FUNCTION design_content_manifest.issue(text,jsonb,text,jsonb,bigint),design_content_manifest.revoke(text),design_content_manifest.issue_read(text,jsonb,text,jsonb,bigint),design_content_manifest.revoke_read(text),design_content_manifest.terminate(text,jsonb,text,text,text) TO design_content_storage_issuer;
REVOKE CREATE ON SCHEMA design_content_manifest FROM design_content_capability;
REVOKE ALL ON ALL TABLES IN SCHEMA design_content_manifest FROM PUBLIC,anon,authenticated,design_identity_runtime,design_content_storage_issuer;
